71	interface Displayables {
72	    sliderGroup: graphic.Group;
73	    handles: [graphic.Path, graphic.Path];
74	    handleLabels: [graphic.Text, graphic.Text];
75	    dataShadowSegs: graphic.Group[];
76	    filler: graphic.Rect;
77	
78	    brushRect: graphic.Rect;
79	
80	    moveHandle: graphic.Rect;
81	    moveHandleIcon: graphic.Path;
82	    // invisible move zone.
83	    moveZone: graphic.Rect;
84	}
85	class SliderZoomView extends DataZoomView {
86	    static type = 'dataZoom.slider';
87	    type = SliderZoomView.type;
88	
89	    dataZoomModel: SliderZoomModel;
90	
91	    private _displayables = {} as Displayables;
92	
93	    private _orient: LayoutOrient;
94	
95	    private _range: number[];
96	
97	    /**
98	     * [coord of the first handle, coord of the second handle]
99	     */
100	    private _handleEnds: number[];
101	
102	    /**
103	     * [length, thick]
104	     */
105	    private _size: number[];
106	
107	    private _handleWidth: number;
108	
109	    private _handleHeight: number;
110	
111	    private _location: PointLike;
112	
113	    private _brushStart: PointLike;
114	    private _brushStartTime: number;
115	
116	    private _dragging: boolean;
117	
118	    private _brushing: boolean;
119	
120	    private _dataShadowInfo: {
121	        thisAxis: Axis
122	        series: SeriesModel
123	        thisDim: string
124	        otherDim: string
125	        otherAxisInverse: boolean
126	    };
127	
128	    // Cached raw data. Avoid rendering data shadow multiple times.
129	    private _shadowData: SeriesData;
130	    private _shadowDim: string;
131	    private _shadowSize: number[];
132	    private _shadowPolygonPts: number[][];
133	    private _shadowPolylinePts: number[][];
134	
135	    init(ecModel: GlobalModel, api: ExtensionAPI) {
136	        this.api = api;
137	
138	        // A unique handler for each dataZoom component
139	        this._onBrush = bind(this._onBrush, this);
140	        this._onBrushEnd = bind(this._onBrushEnd, this);
141	    }
142	
143	    render(
144	        dataZoomModel: SliderZoomModel,
145	        ecModel: GlobalModel,
146	        api: ExtensionAPI,
147	        payload: Payload & {
148	            from: string
149	            type: string
150	        }
151	    ) {
152	        super.render.apply(this, arguments as any);
153	
154	        throttle.createOrUpdate(
155	            this,
156	            '_dispatchZoomAction',
157	            dataZoomModel.get('throttle'),
158	            'fixRate'
159	        );
160	
161	        this._orient = dataZoomModel.getOrient();
162	
163	        if (dataZoomModel.get('show') === false) {
164	            this.group.removeAll();
165	            return;
166	        }
167	
168	        if (dataZoomModel.noTarget()) {
169	            this._clear();
170	            this.group.removeAll();
171	            return;
172	        }
173	
174	        // Notice: this._resetInterval() should not be executed when payload.type
175	        // is 'dataZoom', origin this._range should be maintained, otherwise 'pan'
176	        // or 'zoom' info will be missed because of 'throttle' of this.dispatchAction,
177	        if (!payload || payload.type !== 'dataZoom' || payload.from !== this.uid) {
178	            this._buildView();
179	        }
180	
181	        this._updateView();
182	    }
183	
184	    dispose() {
185	        this._clear();
186	        super.dispose.apply(this, arguments as any);
187	    }
188	
189	    private _clear() {
190	        throttle.clear(this, '_dispatchZoomAction');
191	
192	        const zr = this.api.getZr();
193	        zr.off('mousemove', this._onBrush);
194	        zr.off('mouseup', this._onBrushEnd);
195	    }
196	
197	    private _buildView() {
198	        const thisGroup = this.group;
199	
200	        thisGroup.removeAll();
201	
202	        this._brushing = false;
203	        this._displayables.brushRect = null;
204	
205	        this._resetLocation();
206	        this._resetInterval();
207	
208	        const barGroup = this._displayables.sliderGroup = new graphic.Group();
209	
210	        this._renderBackground();
211	
212	        this._renderHandle();
213	
214	        this._renderDataShadow();
215	
216	        thisGroup.add(barGroup);
217	
218	        this._positionGroup();
219	    }
220	
221	    private _resetLocation() {
222	        const dataZoomModel = this.dataZoomModel;
223	        const api = this.api;
224	        const showMoveHandle = dataZoomModel.get('brushSelect');
225	        const moveHandleSize = showMoveHandle ? DEFAULT_MOVE_HANDLE_SIZE : 0;
226	
227	        const refContainer = layout.createBoxLayoutReference(dataZoomModel, api).refContainer;
228	
229	        // If some of x/y/width/height are not specified,
230	        // auto-adapt according to target grid.
231	        const coordRect = this._findCoordRect();
232	        const edgeGap = dataZoomModel.get('defaultLocationEdgeGap', true) || 0;
233	        // Default align by coordinate system rect.
234	        const positionInfo = this._orient === HORIZONTAL
235	            ? {
236	                // Why using 'right', because right should be used in vertical,
237	                // and it is better to be consistent for dealing with position param merge.
238	                right: refContainer.width - coordRect.x - coordRect.width,
239	                top: refContainer.height - DEFAULT_FILLER_SIZE - edgeGap - moveHandleSize,
240	                width: coordRect.width,
241	                height: DEFAULT_FILLER_SIZE
242	            }
243	            : { // vertical
244	                right: edgeGap,
245	                top: coordRect.y,
246	                width: DEFAULT_FILLER_SIZE,
247	                height: coordRect.height
248	            };
249	
250	        // Do not write back to option and replace value 'ph', because
251	        // the 'ph' value should be recalculated when resize.
252	        const layoutParams = layout.getLayoutParams(dataZoomModel.option);
253	
254	        // Replace the placeholder value.
255	        each(['right', 'top', 'width', 'height'] as const, function (name) {
256	            if (layoutParams[name] === 'ph') {
257	                layoutParams[name] = positionInfo[name];
258	            }
259	        });
260	
261	        const layoutRect = layout.getLayoutRect(
262	            layoutParams,
263	            refContainer
264	        );
265	
266	        this._location = { x: layoutRect.x, y: layoutRect.y };
267	        this._size = [layoutRect.width, layoutRect.height];
268	        this._orient === VERTICAL && this._size.reverse();
269	    }
270	
271	    private _positionGroup() {
272	        const thisGroup = this.group;
273	        const location = this._location;
274	        const orient = this._orient;
275	
276	        // Just use the first axis to determine mapping.
277	        const targetAxisModel = this.dataZoomModel.getFirstTargetAxisModel();
278	        const inverse = targetAxisModel && targetAxisModel.get('inverse');
279	
280	        const sliderGroup = this._displayables.sliderGroup;
281	        const otherAxisInverse = (this._dataShadowInfo || {}).otherAxisInverse;
282	
283	        // Transform barGroup.
284	        sliderGroup.attr(
285	            (orient === HORIZONTAL && !inverse)
286	            ? {scaleY: otherAxisInverse ? 1 : -1, scaleX: 1 }
287	            : (orient === HORIZONTAL && inverse)
288	            ? {scaleY: otherAxisInverse ? 1 : -1, scaleX: -1 }
289	            : (orient === VERTICAL && !inverse)
290	            ? {scaleY: otherAxisInverse ? -1 : 1, scaleX: 1, rotation: Math.PI / 2}
291	            // Don't use Math.PI, considering shadow direction.
292	            : {scaleY: otherAxisInverse ? -1 : 1, scaleX: -1, rotation: Math.PI / 2}
293	        );
294	
295	        // Position barGroup
296	        const rect = thisGroup.getBoundingRect([sliderGroup]);
297	        thisGroup.x = location.x - rect.x;
298	        thisGroup.y = location.y - rect.y;
299	        thisGroup.markRedraw();
300	    }
301	
302	    private _getViewExtent() {
303	        return [0, this._size[0]];
304	    }
305	
306	    private _renderBackground() {
307	        const dataZoomModel = this.dataZoomModel;
308	        const size = this._size;
309	        const barGroup = this._displayables.sliderGroup;
310	        const brushSelect = dataZoomModel.get('brushSelect');
311	
312	        barGroup.add(new Rect({
313	            silent: true,
314	            shape: {
315	                x: 0, y: 0, width: size[0], height: size[1]
316	            },
317	            style: {
318	                fill: dataZoomModel.get('backgroundColor')
319	            },
320	            z2: -40
321	        }));
322	
323	        // Click panel, over shadow, below handles.
324	        const clickPanel = new Rect({
325	            shape: {
326	                x: 0, y: 0, width: size[0], height: size[1]
327	            },
328	            style: {
329	                fill: 'transparent'
330	            },
331	            z2: 0,
332	            onclick: bind(this._onClickPanel, this)
333	        });
334	
335	        const zr = this.api.getZr();
336	        if (brushSelect) {
337	            clickPanel.on('mousedown', this._onBrushStart, this);
338	            clickPanel.cursor = 'crosshair';
339	
340	            zr.on('mousemove', this._onBrush);
341	            zr.on('mouseup', this._onBrushEnd);
342	        }
343	        else {
344	            zr.off('mousemove', this._onBrush);
345	            zr.off('mouseup', this._onBrushEnd);
346	        }
347	
348	        barGroup.add(clickPanel);
349	    }
350	
351	    private _renderDataShadow() {
352	        const info = this._dataShadowInfo = this._prepareDataShadowInfo();
353	
354	        this._displayables.dataShadowSegs = [];
355	
356	        if (!info) {
357	            return;
358	        }
359	
360	        const size = this._size;
361	        const oldSize = this._shadowSize || [];
362	        const seriesModel = info.series;
363	        const data = seriesModel.getRawData();
364	        const candlestickDim = seriesModel.getShadowDim && seriesModel.getShadowDim();
365	        const otherDim: string = candlestickDim && data.getDimensionInfo(candlestickDim)
366	            ? seriesModel.getShadowDim() // @see candlestick
367	            : info.otherDim;
368	
369	        if (otherDim == null) {
370	            return;
371	        }
372	
373	        let polygonPts = this._shadowPolygonPts;
374	        let polylinePts = this._shadowPolylinePts;
375	        // Not re-render if data doesn't change.
376	        if (
377	            data !== this._shadowData || otherDim !== this._shadowDim
378	            || size[0] !== oldSize[0] || size[1] !== oldSize[1]
379	        ) {
380	            const thisDataExtent = data.getDataExtent(info.thisDim);
381	            let otherDataExtent = data.getDataExtent(otherDim);
382	            // Nice extent.
383	            const otherOffset = (otherDataExtent[1] - otherDataExtent[0]) * 0.3;
384	            otherDataExtent = [
385	                otherDataExtent[0] - otherOffset,
386	                otherDataExtent[1] + otherOffset
387	            ];
388	            const otherShadowExtent = [0, size[1]];
389	            const thisShadowExtent = [0, size[0]];
390	
391	            const areaPoints = [[size[0], 0], [0, 0]];
392	            const linePoints: number[][] = [];
393	            const step = thisShadowExtent[1] / (Math.max(1, data.count() - 1));
394	            const normalizationConstant = size[0] / (thisDataExtent[1] - thisDataExtent[0]);
395	            const isTimeAxis = info.thisAxis.type === 'time';
396	            let thisCoord = -step;
397	
398	            // Optimize for large data shadow
399	            const stride = Math.round(data.count() / size[0]);
400	            let lastIsEmpty: boolean;
401	
402	            data.each([info.thisDim, otherDim], function (thisValue: ParsedValue, otherValue: ParsedValue, index) {
403	                if (stride > 0 && (index % stride)) {
404	                    if (!isTimeAxis) {
405	                        thisCoord += step;
406	                    }
407	                    return;
408	                }
409	
410	                thisCoord = isTimeAxis
411	                    ? (+thisValue - thisDataExtent[0]) * normalizationConstant
412	                    : thisCoord + step;
413	
414	                // FIXME
415	                // Should consider axis.min/axis.max when drawing dataShadow.
416	
417	                // FIXME
418	                // 应该使用统一的空判断？还是在list里进行空判断？
419	                const isEmpty = otherValue == null || isNaN(otherValue as number) || otherValue === '';
420	                // See #4235.
421	                const otherCoord = isEmpty
422	                    ? 0 : linearMap(otherValue as number, otherDataExtent, otherShadowExtent, true);
423	
424	                // Attempt to draw data shadow precisely when there are empty value.
425	                if (isEmpty && !lastIsEmpty && index) {
426	                    areaPoints.push([areaPoints[areaPoints.length - 1][0], 0]);
427	                    linePoints.push([linePoints[linePoints.length - 1][0], 0]);
428	                }
429	                else if (!isEmpty && lastIsEmpty) {
430	                    areaPoints.push([thisCoord, 0]);
431	                    linePoints.push([thisCoord, 0]);
432	                }
433	
434	                if (!isEmpty) {
435	                    areaPoints.push([thisCoord, otherCoord]);
436	                    linePoints.push([thisCoord, otherCoord]);
437	                }
438	
439	                lastIsEmpty = isEmpty;
440	            });
441	
442	            polygonPts = this._shadowPolygonPts = areaPoints;
443	            polylinePts = this._shadowPolylinePts = linePoints;
444	
445	        }
446	        this._shadowData = data;
447	        this._shadowDim = otherDim;
448	        this._shadowSize = [size[0], size[1]];
449	
450	        const dataZoomModel = this.dataZoomModel;
451	
452	        function createDataShadowGroup(isSelectedArea?: boolean) {
453	            const model = dataZoomModel.getModel(isSelectedArea ? 'selectedDataBackground' : 'dataBackground');
454	            const group = new graphic.Group();
455	            const polygon = new graphic.Polygon({
456	                shape: { points: polygonPts },
457	                segmentIgnoreThreshold: 1,
458	                style: model.getModel('areaStyle').getAreaStyle(),
459	                silent: true,
460	                z2: -20
461	            });
462	            const polyline = new graphic.Polyline({
463	                shape: { points: polylinePts },
464	                segmentIgnoreThreshold: 1,
465	                style: model.getModel('lineStyle').getLineStyle(),
466	                silent: true,
467	                z2: -19
468	            });
469	            group.add(polygon);
470	            group.add(polyline);
471	            return group;
472	        }
473	
474	        // let dataBackgroundModel = dataZoomModel.getModel('dataBackground');
475	        for (let i = 0; i < 3; i++) {
476	            const group = createDataShadowGroup(i === 1);
477	            this._displayables.sliderGroup.add(group);
478	            this._displayables.dataShadowSegs.push(group);
479	        }
480	    }
481	
482	    private _prepareDataShadowInfo() {
483	        const dataZoomModel = this.dataZoomModel;
484	        const showDataShadow = dataZoomModel.get('showDataShadow');
485	
486	        if (showDataShadow === false) {
487	            return;
488	        }
489	
490	        // Find a representative series.
491	        let result: SliderZoomView['_dataShadowInfo'];
492	        const ecModel = this.ecModel;
493	
494	        dataZoomModel.eachTargetAxis(function (axisDim, axisIndex) {
495	            const seriesModels = dataZoomModel
496	                .getAxisProxy(axisDim, axisIndex)
497	                .getTargetSeriesModels();
498	
499	            each(seriesModels, function (seriesModel) {
500	                if (result) {
501	                    return;
502	                }
503	
504	                if (showDataShadow !== true && indexOf(
505	                    SHOW_DATA_SHADOW_SERIES_TYPE, seriesModel.get('type')
506	                ) < 0
507	                ) {
508	                    return;
509	                }
510	
511	                const thisAxis = (
512	                    ecModel.getComponent(getAxisMainType(axisDim), axisIndex) as AxisBaseModel
513	                ).axis;
514	                let otherDim = getOtherDim(axisDim);
515	                let otherAxisInverse;
516	                const coordSys = seriesModel.coordinateSystem;
517	
518	                if (otherDim != null && coordSys.getOtherAxis) {
519	                    otherAxisInverse = coordSys.getOtherAxis(thisAxis).inverse;
520	                }
521	
522	                otherDim = seriesModel.getData().mapDimension(otherDim);
523	                const thisDim = seriesModel.getData().mapDimension(axisDim);
524	
525	                result = {
526	                    thisAxis: thisAxis,
527	                    series: seriesModel,
528	                    thisDim: thisDim,
529	                    otherDim: otherDim,
530	                    otherAxisInverse: otherAxisInverse
531	                };
532	
533	            }, this);
534	
535	        }, this);
536	
537	        return result;
538	    }
539	
540	    private _renderHandle() {
541	        const thisGroup = this.group;
542	        const displayables = this._displayables;
543	        const handles: [graphic.Path, graphic.Path] = displayables.handles = [null, null];
544	        const handleLabels: [graphic.Text, graphic.Text] = displayables.handleLabels = [null, null];
545	        const sliderGroup = this._displayables.sliderGroup;
546	        const size = this._size;
547	        const dataZoomModel = this.dataZoomModel;
548	        const api = this.api;
549	
550	        const borderRadius = dataZoomModel.get('borderRadius') || 0;
551	
552	        const brushSelect = dataZoomModel.get('brushSelect');
553	
554	        const filler = displayables.filler = new Rect({
555	            silent: brushSelect,
556	            style: {
557	                fill: dataZoomModel.get('fillerColor')
558	            },
559	            textConfig: {
560	                position: 'inside'
561	            }
562	        });
563	
564	        sliderGroup.add(filler);
565	
566	        // Frame border.
567	        sliderGroup.add(new Rect({
568	            silent: true,
569	            subPixelOptimize: true,
570	            shape: {
571	                x: 0,
572	                y: 0,
573	                width: size[0],
574	                height: size[1],
575	                r: borderRadius
576	            },
577	            style: {
578	                // deprecated option
579	                stroke: dataZoomModel.get('dataBackgroundColor' as any)
580	                    || dataZoomModel.get('borderColor'),
581	                lineWidth: DEFAULT_FRAME_BORDER_WIDTH,
582	                fill: tokens.color.transparent
583	            }
584	        }));
585	
586	        // Left and right handle to resize
587	        each([0, 1] as const, function (handleIndex) {
588	            let iconStr = dataZoomModel.get('handleIcon');
589	            if (
590	                !symbolBuildProxies[iconStr]
591	                && iconStr.indexOf('path://') < 0
592	                && iconStr.indexOf('image://') < 0
593	            ) {
594	                // Compatitable with the old icon parsers. Which can use a path string without path://
595	                iconStr = 'path://' + iconStr;
596	                if (__DEV__) {
597	                    deprecateLog('handleIcon now needs \'path://\' prefix when using a path string');
598	                }
599	            }
600	            const path = createSymbol(
601	                iconStr,
602	                -1, 0, 2, 2, null, true
603	            ) as graphic.Path;
604	            path.attr({
605	                cursor: getCursor(this._orient),
606	                draggable: true,
607	                drift: bind(this._onDragMove, this, handleIndex),
608	                ondragend: bind(this._onDragEnd, this),
609	                onmouseover: bind(this._showDataInfo, this, true),
610	                onmouseout: bind(this._showDataInfo, this, false),
611	                z2: 5
612	            });
613	
614	            const bRect = path.getBoundingRect();
615	            const handleSize = dataZoomModel.get('handleSize');
616	
617	            this._handleHeight = parsePercent(handleSize, this._size[1]);
618	            this._handleWidth = bRect.width / bRect.height * this._handleHeight;
619	
620	            path.setStyle(dataZoomModel.getModel('handleStyle').getItemStyle());
621	            path.style.strokeNoScale = true;
622	            path.rectHover = true;
623	
624	            path.ensureState('emphasis').style = dataZoomModel.getModel(['emphasis', 'handleStyle']).getItemStyle();
625	            enableHoverEmphasis(path);
626	
627	            const handleColor = dataZoomModel.get('handleColor' as any); // deprecated option
628	            // Compatitable with previous version
629	            if (handleColor != null) {
630	                path.style.fill = handleColor;
631	            }
632	
633	            sliderGroup.add(handles[handleIndex] = path);
634	
635	            const textStyleModel = dataZoomModel.getModel('textStyle');
636	            const handleLabel = dataZoomModel.get('handleLabel') || {};
637	            const handleLabelShow = handleLabel.show || false;
638	
639	            thisGroup.add(
640	                handleLabels[handleIndex] = new graphic.Text({
641	                silent: true,
642	                invisible: !handleLabelShow,
643	                style: createTextStyle(textStyleModel, {
644	                    x: 0, y: 0, text: '',
645	                    verticalAlign: 'middle',
646	                    align: 'center',
647	                    fill: textStyleModel.getTextColor(),
648	                    font: textStyleModel.getFont()
649	                }),
650	                z2: 10
651	            }));
652	
653	        }, this);
654	
655	        // Handle to move. Only visible when brushSelect is set true.
656	        let actualMoveZone: Displayable = filler;
657	        if (brushSelect) {
658	            const moveHandleHeight = parsePercent(dataZoomModel.get('moveHandleSize'), size[1]);
659	            const moveHandle = displayables.moveHandle = new graphic.Rect({
660	                style: dataZoomModel.getModel('moveHandleStyle').getItemStyle(),
661	                silent: true,
662	                shape: {
663	                    r: [0, 0, 2, 2],
664	                    y: size[1] - 0.5,
665	                    height: moveHandleHeight
666	                }
667	            });
668	            const iconSize = moveHandleHeight * 0.8;
669	            const moveHandleIcon = displayables.moveHandleIcon = createSymbol(
670	                dataZoomModel.get('moveHandleIcon'),
671	                -iconSize / 2, -iconSize / 2, iconSize, iconSize,
672	                tokens.color.neutral00,
673	                true
674	            );
675	            moveHandleIcon.silent = true;
676	            moveHandleIcon.y = size[1] + moveHandleHeight / 2 - 0.5;
677	
678	            moveHandle.ensureState('emphasis').style = dataZoomModel.getModel(
679	                ['emphasis', 'moveHandleStyle']
680	            ).getItemStyle();
681	
682	            const moveZoneExpandSize = Math.min(size[1] / 2, Math.max(moveHandleHeight, 10));
683	            actualMoveZone = displayables.moveZone = new graphic.Rect({
684	                invisible: true,
685	                shape: {
686	                    y: size[1] - moveZoneExpandSize,
687	                    height: moveHandleHeight + moveZoneExpandSize
688	                }
689	            });
690	
691	            actualMoveZone.on('mouseover', () => {
692	                api.enterEmphasis(moveHandle);
693	            })
694	                .on('mouseout', () => {
695	                    api.leaveEmphasis(moveHandle);
696	                });
697	
698	            sliderGroup.add(moveHandle);
699	            sliderGroup.add(moveHandleIcon);
700	            sliderGroup.add(actualMoveZone);
701	        }
702	
703	        actualMoveZone.attr({
704	            draggable: true,
705	            cursor: 'default',
706	            drift: bind(this._onDragMove, this, 'all'),
707	            ondragstart: bind(this._showDataInfo, this, true),
708	            ondragend: bind(this._onDragEnd, this),
709	            onmouseover: bind(this._showDataInfo, this, true),
710	            onmouseout: bind(this._showDataInfo, this, false)
711	        });
712	    }
