714	    private _resetInterval() {
715	        const range = this._range = this.dataZoomModel.getPercentRange();
716	        const viewExtent = this._getViewExtent();
717	
718	        this._handleEnds = [
719	            linearMap(range[0], [0, 100], viewExtent, true),
720	            linearMap(range[1], [0, 100], viewExtent, true)
721	        ];
722	    }
