724	    private _updateInterval(handleIndex: 0 | 1 | 'all', delta: number): boolean {
725	        const dataZoomModel = this.dataZoomModel;
726	        const handleEnds = this._handleEnds;
727	        const viewExtend = this._getViewExtent();
728	        const minMaxSpan = dataZoomModel.findRepresentativeAxisProxy().getMinMaxSpan();
729	        const percentExtent = [0, 100];
730	
731	        sliderMove(
732	            delta,
733	            handleEnds,
734	            viewExtend,
735	            dataZoomModel.get('zoomLock') ? 'all' : handleIndex,
736	            minMaxSpan.minSpan != null
737	                ? linearMap(minMaxSpan.minSpan, percentExtent, viewExtend, true) : null,
738	            minMaxSpan.maxSpan != null
739	                ? linearMap(minMaxSpan.maxSpan, percentExtent, viewExtend, true) : null
740	        );
741	
742	        const lastRange = this._range;
743	        const range = this._range = asc([
744	            linearMap(handleEnds[0], viewExtend, percentExtent, true),
745	            linearMap(handleEnds[1], viewExtend, percentExtent, true)
746	        ]);
747	
748	        return !lastRange || lastRange[0] !== range[0] || lastRange[1] !== range[1];
749	    }
