751	    private _updateView(nonRealtime?: boolean) {
752	        const displaybles = this._displayables;
753	        const handleEnds = this._handleEnds;
754	        const handleInterval = asc(handleEnds.slice());
755	        const size = this._size;
756	
757	        each([0, 1] as const, function (handleIndex) {
758	            // Handles
759	            const handle = displaybles.handles[handleIndex];
760	            const handleHeight = this._handleHeight;
761	            (handle as graphic.Path).attr({
762	                scaleX: handleHeight / 2,
763	                scaleY: handleHeight / 2,
764	                // This is a trick, by adding an extra tiny offset to let the default handle's end point align to the drag window.
765	                // NOTE: It may affect some custom shapes a bit. But we prefer to have better result by default.
766	                x: handleEnds[handleIndex] + (handleIndex ? -1 : 1),
767	                y: size[1] / 2 - handleHeight / 2
768	            });
769	        }, this);
770	
771	        // Filler
772	        displaybles.filler.setShape({
773	            x: handleInterval[0],
774	            y: 0,
775	            width: handleInterval[1] - handleInterval[0],
776	            height: size[1]
777	        });
778	
779	        const viewExtent = {
780	            x: handleInterval[0],
781	            width: handleInterval[1] - handleInterval[0]
782	        };
783	        // Move handle
784	        if (displaybles.moveHandle) {
785	            displaybles.moveHandle.setShape(viewExtent);
786	            displaybles.moveZone.setShape(viewExtent);
787	            // Force update path on the invisible object
788	            displaybles.moveZone.getBoundingRect();
789	            displaybles.moveHandleIcon && displaybles.moveHandleIcon.attr('x', viewExtent.x + viewExtent.width / 2);
790	        }
791	
792	        // update clip path of shadow.
793	        const dataShadowSegs = displaybles.dataShadowSegs;
794	        const segIntervals = [0, handleInterval[0], handleInterval[1], size[0]];
795	
796	        for (let i = 0; i < dataShadowSegs.length; i++) {
797	            const segGroup = dataShadowSegs[i];
798	            let clipPath = segGroup.getClipPath();
799	            if (!clipPath) {
800	                clipPath = new graphic.Rect();
801	                segGroup.setClipPath(clipPath);
802	            }
803	            clipPath.setShape({
804	                x: segIntervals[i],
805	                y: 0,
806	                width: segIntervals[i + 1] - segIntervals[i],
807	                height: size[1]
808	            });
809	        }
810	
811	        this._updateDataInfo(nonRealtime);
812	    }
