814	    private _updateDataInfo(nonRealtime?: boolean) {
815	        const dataZoomModel = this.dataZoomModel;
816	        const displaybles = this._displayables;
817	        const handleLabels = displaybles.handleLabels;
818	        const orient = this._orient;
819	        let labelTexts = ['', ''];
820	
821	        // FIXME
822	        // date型，支持formatter，autoformatter（ec2 date.getAutoFormatter）
823	        if (dataZoomModel.get('showDetail')) {
824	            const axisProxy = dataZoomModel.findRepresentativeAxisProxy();
825	
826	            if (axisProxy) {
827	                const axis = axisProxy.getAxisModel().axis;
828	                const range = this._range;
829	
830	                const dataInterval = nonRealtime
831	                    // See #4434, data and axis are not processed and reset yet in non-realtime mode.
832	                    ? axisProxy.calculateDataWindow({
833	                        start: range[0], end: range[1]
834	                    }).valueWindow
835	                    : axisProxy.getDataValueWindow();
836	
837	                labelTexts = [
838	                    this._formatLabel(dataInterval[0], axis),
839	                    this._formatLabel(dataInterval[1], axis)
840	                ];
841	            }
842	        }
843	
844	        const orderedHandleEnds = asc(this._handleEnds.slice());
845	
846	        setLabel.call(this, 0);
847	        setLabel.call(this, 1);
848	
849	        function setLabel(this: SliderZoomView, handleIndex: 0 | 1) {
850	            // Label
851	            // Text should not transform by barGroup.
852	            // Ignore handlers transform
853	            const barTransform = graphic.getTransform(
854	                displaybles.handles[handleIndex].parent, this.group
855	            );
856	            const direction = graphic.transformDirection(
857	                handleIndex === 0 ? 'right' : 'left', barTransform
858	            );
859	            const offset = this._handleWidth / 2 + LABEL_GAP;
860	            const textPoint = graphic.applyTransform(
861	                [
862	                    orderedHandleEnds[handleIndex] + (handleIndex === 0 ? -offset : offset),
863	                    this._size[1] / 2
864	                ],
865	                barTransform
866	            );
867	            handleLabels[handleIndex].setStyle({
868	                x: textPoint[0],
869	                y: textPoint[1],
870	                verticalAlign: orient === HORIZONTAL ? 'middle' : direction as ZRTextVerticalAlign,
871	                align: orient === HORIZONTAL ? direction as ZRTextAlign : 'center',
872	                text: labelTexts[handleIndex]
873	            });
874	        }
875	    }
