877	    private _formatLabel(value: ParsedValue, axis: Axis) {
878	        const dataZoomModel = this.dataZoomModel;
879	        const labelFormatter = dataZoomModel.get('labelFormatter');
880	
881	        let labelPrecision = dataZoomModel.get('labelPrecision');
882	        if (labelPrecision == null || labelPrecision === 'auto') {
883	            labelPrecision = axis.getPixelPrecision();
884	        }
885	
886	        const valueStr = (value == null || isNaN(value as number))
887	            ? ''
888	            // FIXME Glue code
889	            : (axis.type === 'category' || axis.type === 'time')
890	                ? axis.scale.getLabel({
891	                    value: Math.round(value as number)
892	                })
893	                // param of toFixed should less then 20.
894	                : (value as number).toFixed(Math.min(labelPrecision as number, 20));
895	
896	        return isFunction(labelFormatter)
897	            ? labelFormatter(value as number, valueStr)
898	            : isString(labelFormatter)
899	                ? labelFormatter.replace('{value}', valueStr)
900	                : valueStr;
901	    }
