903	    /**
904	     * @param isEmphasis true: show, false: hide
905	     */
906	    private _showDataInfo(isEmphasis?: boolean) {
907	        const handleLabel = this.dataZoomModel.get('handleLabel') || {};
908	        const normalShow = handleLabel.show || false;
909	        const emphasisHandleLabel = this.dataZoomModel.getModel(['emphasis', 'handleLabel']);
910	        const emphasisShow = emphasisHandleLabel.get('show') || false;
911	        // Dragging is considered as emphasis, unless emphasisShow is false
912	        const toShow = (isEmphasis || this._dragging)
913	            ? emphasisShow
914	            : normalShow;
915	        const displayables = this._displayables;
916	        const handleLabels = displayables.handleLabels;
917	        handleLabels[0].attr('invisible', !toShow);
918	        handleLabels[1].attr('invisible', !toShow);
919	
920	        // Highlight move handle
921	        displayables.moveHandle
922	            && this.api[toShow ? 'enterEmphasis' : 'leaveEmphasis'](displayables.moveHandle, 1);
923	    }
