925	    private _onDragMove(handleIndex: 0 | 1 | 'all', dx: number, dy: number, event: ZRElementEvent) {
926	        this._dragging = true;
927	
928	        // For mobile device, prevent screen slider on the button.
929	        eventTool.stop(event.event);
930	
931	        // Transform dx, dy to bar coordination.
932	        const barTransform = this._displayables.sliderGroup.getLocalTransform();
933	        const vertex = graphic.applyTransform([dx, dy], barTransform, true);
934	
935	        const changed = this._updateInterval(handleIndex, vertex[0]);
936	
937	        const realtime = this.dataZoomModel.get('realtime');
938	
939	        this._updateView(!realtime);
940	
941	        // Avoid dispatch dataZoom repeatly but range not changed,
942	        // which cause bad visual effect when progressive enabled.
943	        changed && realtime && this._dispatchZoomAction(true);
944	    }
945	
946	    private _onDragEnd() {
947	        this._dragging = false;
948	        this._showDataInfo(false);
949	
950	        // While in realtime mode and stream mode, dispatch action when
951	        // drag end will cause the whole view rerender, which is unnecessary.
952	        const realtime = this.dataZoomModel.get('realtime');
953	        !realtime && this._dispatchZoomAction(false);
954	    }
