956	    private _onClickPanel(e: ZRElementEvent) {
957	        const size = this._size;
958	        const localPoint = this._displayables.sliderGroup.transformCoordToLocal(e.offsetX, e.offsetY);
959	
960	        if (localPoint[0] < 0 || localPoint[0] > size[0]
961	            || localPoint[1] < 0 || localPoint[1] > size[1]
962	        ) {
963	            return;
964	        }
965	
966	        const handleEnds = this._handleEnds;
967	        const center = (handleEnds[0] + handleEnds[1]) / 2;
968	
969	        const changed = this._updateInterval('all', localPoint[0] - center);
970	        this._updateView();
971	        changed && this._dispatchZoomAction(false);
972	    }
