985	    private _onBrushEnd(e: ZRElementEvent) {
986	        if (!this._brushing) {
987	            return;
988	        }
989	
990	        const brushRect = this._displayables.brushRect;
991	        this._brushing = false;
992	
993	        if (!brushRect) {
994	            return;
995	        }
996	
997	        brushRect.attr('ignore', true);
998	
999	        const brushShape = brushRect.shape;
1000

1000	
1001	        const brushEndTime = +new Date();
1002	        // console.log(brushEndTime - this._brushStartTime);
1003	        if (brushEndTime - this._brushStartTime < 200 && Math.abs(brushShape.width) < 5) {
1004	            // Will treat it as a click
1005	            return;
1006	        }
1007	
1008	        const viewExtend = this._getViewExtent();
1009	        const percentExtent = [0, 100];
1010	
1011	        const handleEnds = this._handleEnds = [brushShape.x, brushShape.x + brushShape.width];
1012	        const minMaxSpan = this.dataZoomModel.findRepresentativeAxisProxy().getMinMaxSpan();
1013	        // Restrict range.
1014	        sliderMove(
1015	            0,
1016	            handleEnds,
1017	            viewExtend,
1018	            0,
1019	            minMaxSpan.minSpan != null
1020	                ? linearMap(minMaxSpan.minSpan, percentExtent, viewExtend, true) : null,
1021	            minMaxSpan.maxSpan != null
1022	                ? linearMap(minMaxSpan.maxSpan, percentExtent, viewExtend, true) : null
1023	        );
1024	
1025	        this._range = asc([
1026	            linearMap(handleEnds[0], viewExtend, percentExtent, true),
1027	            linearMap(handleEnds[1], viewExtend, percentExtent, true)
1028	        ]);
1029	
1030	        this._updateView();
