1044	    private _updateBrushRect(mouseX: number, mouseY: number) {
1045	        const displayables = this._displayables;
1046	        const dataZoomModel = this.dataZoomModel;
1047	        let brushRect = displayables.brushRect;
1048	        if (!brushRect) {
1049	            brushRect = displayables.brushRect = new Rect({
1050	                silent: true,
1051	                style: dataZoomModel.getModel('brushStyle').getItemStyle()
1052	            });
1053	            displayables.sliderGroup.add(brushRect);
1054	        }
1055	
1056	        brushRect.attr('ignore', false);
1057	
1058	        const brushStart = this._brushStart;
1059	
1060	        const sliderGroup = this._displayables.sliderGroup;
1061	
1062	        const endPoint = sliderGroup.transformCoordToLocal(mouseX, mouseY);
1063	        const startPoint = sliderGroup.transformCoordToLocal(brushStart.x, brushStart.y);
1064	
