1092	        // Find the grid corresponding to the first axis referred by dataZoom.
1093	        let rect: RectLike;
1094	        const coordSysInfoList = collectReferCoordSysModelInfo(this.dataZoomModel).infoList;
1095	
1096	        if (!rect && coordSysInfoList.length) {
1097	            const coordSys = coordSysInfoList[0].model.coordinateSystem;
1098	            rect = coordSys.getRect && coordSys.getRect();
1099	        }
1100	
1101	        if (!rect) {
1102	            const width = this.api.getWidth();
1103	            const height = this.api.getHeight();
1104	            rect = {
1105	                x: width * 0.2,
1106	                y: height * 0.2,
1107	                width: width * 0.6,
1108	                height: height * 0.6
1109	            };
1110	        }
1111	
1112	        return rect;
