70	        axisIndex: number,
71	        dataZoomModel: DataZoomModel,
72	        ecModel: GlobalModel
73	    ) {
74	        this._dimName = dimName;
75	
76	        this._axisIndex = axisIndex;
77	
78	        this.ecModel = ecModel;
79	
80	        this._dataZoomModel = dataZoomModel;
