110	    getTargetSeriesModels() {
111	        const seriesModels: SeriesModel[] = [];
112	
113	        this.ecModel.eachSeries(function (seriesModel) {
114	            if (isCoordSupported(seriesModel)) {
115	                const axisMainType = getAxisMainType(this._dimName);
116	                const axisModel = seriesModel.getReferringComponents(axisMainType, SINGLE_REFERRING).models[0];
117	                if (axisModel && this._axisIndex === axisModel.componentIndex) {
118	                    seriesModels.push(seriesModel);
