134	    /**
135	     * Only calculate by given range and this._dataExtent, do not change anything.
136	     */
137	    calculateDataWindow(opt?: {
138	        start?: number
139	        end?: number
140	        startValue?: number | string | Date
141	        endValue?: number | string | Date
142	    }) {
143	        const dataExtent = this._dataExtent;
144	        const axisModel = this.getAxisModel();
145	        const scale = axisModel.axis.scale;
146	        const rangePropMode = this._dataZoomModel.getRangePropMode();
147	        const percentExtent = [0, 100];
148	        const percentWindow = [] as unknown as [number, number];
149	        const valueWindow = [] as unknown as [number, number];
150	        let hasPropModeValue;
151	
152	        each(['start', 'end'] as const, function (prop, idx) {
153	            let boundPercent = opt[prop];
154	            let boundValue = opt[prop + 'Value' as 'startValue' | 'endValue'];
155	
156	            // Notice: dataZoom is based either on `percentProp` ('start', 'end') or
157	            // on `valueProp` ('startValue', 'endValue'). (They are based on the data extent
158	            // but not min/max of axis, which will be calculated by data window then).
159	            // The former one is suitable for cases that a dataZoom component controls multiple
160	            // axes with different unit or extent, and the latter one is suitable for accurate
161	            // zoom by pixel (e.g., in dataZoomSelect).
162	            // we use `getRangePropMode()` to mark which prop is used. `rangePropMode` is updated
163	            // only when setOption or dispatchAction, otherwise it remains its original value.
164	            // (Why not only record `percentProp` and always map to `valueProp`? Because
165	            // the map `valueProp` -> `percentProp` -> `valueProp` probably not the original
166	            // `valueProp`. consider two axes constrolled by one dataZoom. They have different
167	            // data extent. All of values that are overflow the `dataExtent` will be calculated
