388	        const axisModel = this.getAxisModel();
389	
390	        const percentWindow = this._percentWindow;
391	        const valueWindow = this._valueWindow;
392	
393	        if (!percentWindow) {
394	            return;
395	        }
396	
397	        // [0, 500]: arbitrary value, guess axis extent.
398	        let precision = numberUtil.getPixelPrecision(valueWindow, [0, 500]);
399	        precision = Math.min(precision, 20);
400	
401	        // For value axis, if min/max/scale are not set, we just use the extent obtained
402	        // by series data, which may be a little different from the extent calculated by
403	        // `axisHelper.getScaleExtent`. But the different just affects the experience a
404	        // little when zooming. So it will not be fixed until some users require it strongly.
405	        const rawExtentInfo = axisModel.axis.scale.rawExtentInfo;
406	        if (percentWindow[0] !== 0) {
407	            rawExtentInfo.setDeterminedMinMax('min', +valueWindow[0].toFixed(precision));
408	        }
409	        if (percentWindow[1] !== 100) {
