import { EChartsType } from '../../src/echarts';
import SliderZoomView from '../../src/component/dataZoom/SliderZoomView';

describe('dataZoom-single-point-position', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart({ width: 800, height: 600 });
    });

    afterEach(function () {
        chart.dispose();
    });

    it('slider group position should be finite when the series has only one data point', function () {
        chart.setOption({
            animation: false,
            dataZoom: {},
            xAxis: {
                type: 'time'
            },
            yAxis: {
                show: false,
                type: 'value',
                min: 0,
                max: 100
            },
            series: [{
                animation: false,
                type: 'bar',
                barWidth: 4,
                data: [
                    {
                        timestamp: 1753548900000,
                        value: [1753548900000, 50, 0]
                    }
                ],
                dimensions: ['timestamp', 'value'],
                encode: {
                    x: 0,
                    y: 1
                }
            }]
        });

        const dataZoomModel = getECModel(chart).getComponent('dataZoom', 0);
        const view = (chart as any).getViewOfComponentModel(dataZoomModel) as SliderZoomView;

        expect(view.group).toBeTruthy();
        expect(isNaN(view.group.x)).toEqual(false);
        expect(isNaN(view.group.y)).toEqual(false);
        expect(isFinite(view.group.x)).toEqual(true);
        expect(isFinite(view.group.y)).toEqual(true);
    });

});

